# `meta_V(v)` with `method = :REML` AND prior row `weights`, pinned to drmTMB 0.8.1 (fixtures/meta_v_reml_weights/,
# regenerated by make_reference.R). Same bounds as test_meta_v_reml.jl: |logLik diff| <= 1e-4, fixed effects within
# 1e-3 R SE, log sigma within 5e-3, SEs within 1e-3 relative.
# Criterion (checked against R to 7 digits): the weighted ML objective at the REML estimates plus the restriction
#   0.5 logdet(X' diag(w_i / Omega_i) X) - 0.5 p log 2pi,   Omega_i = v_i + sigma^2.
using DRModels, Test, DelimitedFiles, LinearAlgebra
using StatsModels: @formula

const _MVW_DIR = joinpath(@__DIR__, "fixtures", "meta_v_reml_weights")
const _MVW_D = let (m, h) = readdlm(joinpath(_MVW_DIR, "data_meta_reml_weights.csv"), ',', Any; header = true)
    h = String.(vec(h)); col(n) = m[:, findfirst(==(n), h)]
    (; g = String.(col("g")), x1 = Float64.(col("x1")), vi = Float64.(col("vi")), yi = Float64.(col("yi")),
       w = Float64.(col("w")), wi = Float64.(col("wi")), w1 = Float64.(col("w1")))
end
const _MVW_REF = let (m, h) = readdlm(joinpath(_MVW_DIR, "ref_meta_reml_weights.csv"), ',', Any; header = true, comments = true, comment_char = '#')
    Dict((String(m[i, 1]), String(m[i, 2])) => (est = Float64(m[i, 3]), se = m[i, 4] isa Number ? Float64(m[i, 4]) : NaN)
         for i in 1:size(m, 1))
end

function _mvw_check(fit, cell, reml::Bool)
    R(k) = _MVW_REF[(cell, k)]
    @test fit.estim_method === (reml ? :REML : :ML)
    @test fit.converged
    @test abs(fit.loglik - R("logLik").est) <= 1e-4
    se = sqrt.(diag(fit.vcov))
    for (j, k) in enumerate(["mu:(Intercept)", "mu:x1", "sigma:(Intercept)"])
        @test abs(fit.theta[j] - R(k).est) <= (j <= 2 ? 1e-3 * R(k).se : 5e-3)
        @test abs(se[j] - R(k).se) <= 1e-3 * R(k).se
    end
end

@testset "meta_V + REML + weights agrees with R drmTMB 0.8.1" begin
    d = _MVW_D
    f = bf(@formula(yi ~ x1 + meta_V(vi)), @formula(sigma ~ 1))
    for (wn, w) in (("w", d.w), ("wi", d.wi))
        @testset "weights $wn" begin
            _mvw_check(drm(f, Gaussian(); data = d, weights = w, method = :REML), "metaw_reml_$wn", true)
            _mvw_check(drm(f, Gaussian(); data = d, weights = w), "metaw_ml_$wn", false)
        end
    end
    @testset "independent oracle for the restriction" begin
        fit = drm(f, Gaussian(); data = d, weights = d.w, method = :REML)
        n = length(d.yi); X = [ones(n) d.x1]
        b = fit.theta[1:2]; s2 = exp(2 * fit.theta[3]); Om = d.vi .+ s2; r = d.yi .- X * b
        nllml = 0.5 * sum(d.w .* (log.(Om) .+ r .^ 2 ./ Om)) + 0.5 * sum(d.w) * log(2π)
        H = Symmetric(X' * (X .* (d.w ./ Om)))
        @test -(nllml + 0.5 * logdet(H) - 0.5 * 2 * log(2π)) ≈ fit.loglik atol = 1e-8
        @test ml_loglik(fit) ≈ -nllml atol = 1e-8
        @test reml_loglik(fit) == fit.loglik
    end
    @testset "unit weights reproduce the unweighted REML fit" begin
        base = drm(f, Gaussian(); data = d, method = :REML)
        one = drm(f, Gaussian(); data = d, weights = d.w1, method = :REML)
        @test one.theta ≈ base.theta rtol = 1e-10
        @test one.loglik ≈ base.loglik atol = 1e-10
        @test one.vcov ≈ base.vcov rtol = 1e-8
        R = _MVW_REF
        @test abs(R[("metaw_reml_w1", "logLik")].est - R[("meta_reml_unweighted", "logLik")].est) <= 1e-8   # R itself
        @test abs(one.loglik - R[("metaw_reml_w1", "logLik")].est) <= 1e-4
    end
    @testset "meta_V + (1 | g) with weights is refused by name" begin
        g = bf(@formula(yi ~ x1 + meta_V(vi) + (1 | g)), @formula(sigma ~ 1))
        for m in (:ML, :REML)
            err = try drm(g, Gaussian(); data = d, weights = d.w, method = m); nothing catch e e end
            @test err isa ArgumentError
            @test occursin("`weights` together with `meta_V(...)` and a random effect", err.msg) && occursin("Try `meta_V(...)`", err.msg)
        end
        @test drm(g, Gaussian(); data = d, method = :REML).converged   # without weights it still fits
    end
end
